MAX_ROM = 0x100000


def decode_ihex(source):
    """Decode dense, zero-based EPROM dumps; reject sparse/overlapping records."""
    image, seen = bytearray(MAX_ROM), bytearray(MAX_ROM)
    base = end = count = 0
    eof = False
    for number, line in enumerate(source.splitlines(), 1):
        line = line.strip()
        if not line:
            continue
        if eof or not re.fullmatch(rb':[0-9a-fA-F]+', line) or len(line) % 2 != 1:
            raise ValueError(f'invalid Intel HEX record at line {number}')
        record = bytes.fromhex(line[1:].decode('ascii'))
        if len(record) < 5 or len(record) != record[0] + 5 or sum(record) & 255:
            raise ValueError(f'invalid Intel HEX length or checksum at line {number}')
        offset, kind, data = int.from_bytes(record[1:3], 'big'), record[3], record[4:-1]
        if kind == 0:
            start, stop = base + offset, base + offset + len(data)
            if stop > MAX_ROM or offset + len(data) > 0x10000 or any(seen[start:stop]):
                raise ValueError(f'overlapping or out-of-range Intel HEX data at line {number}')
            image[start:stop] = data
            seen[start:stop] = b'\x01' * len(data)
            end, count = max(end, stop), count + len(data)
        elif offset == 0 and kind == 1 and not data:
            eof = True
        elif offset == 0 and kind in (2, 4) and len(data) == 2:
            base = int.from_bytes(data, 'big') << (4 if kind == 2 else 16)
        elif offset != 0 or kind not in (3, 5) or len(data) != 4:
            raise ValueError(f'unsupported Intel HEX record at line {number}')
    if not eof or not count or count != end:
        raise ValueError('Intel HEX must have EOF and dense, zero-based data')
    return bytes(image[:end])


def load_rom(path):
    data = path.read_bytes()
    if path.suffix.lower() == '.hex':
        return decode_ihex(data)
    if not 0 < len(data) <= MAX_ROM:
        raise ValueError(f'{path}: binary ROM must contain 1..{MAX_ROM} bytes')
    return data


RING_ON = re.compile(rb'\x2a(..)\x7d\xe6\x10\x6f\x26\x00\x7d\xb4', re.S)


ABANDON_NOTIFY = re.compile(rb'\x21\x00\x02\xe5\x21(.)\x00\xe5\xcd(..)\xe1\xe1', re.S)


RING_GATES = re.compile(rb'\x3a(..)\xe6\x07\xb7\x20\x15\x3a(..)\xe6\x20\xb7\x28\x0d', re.S)


DATA_TIMEOUT = re.compile(rb'\x3a(..)\xfe\x02\x28.\x3a\1\xfe\x07\x28', re.S)


NCC_SETUP = re.compile(rb'\x3e\x01\x32(..)\x3a(..)\xf6\x02\x32\2', re.S)


def word_hex(raw):
    return hex(int.from_bytes(raw, 'little'))


def ring_candidates(rom, *, voice_tasks=(9,)):
    """Find a compiler-pattern match, never a license to modify a ROM."""
    for m in RING_ON.finditer(rom):
        on = m.start()
        state = on + 0x32
        if rom[state:state + 11] != b'\x2a' + m[1] + b'\x7d\xe6\x40\x6f\x26\x00\x7d\xb4':
            continue
        notify = ABANDON_NOTIFY.match(rom, state + 0x1D)
        first_gates = RING_GATES.match(rom, on + 0x0E)
        later_gates = RING_GATES.match(rom, state + 0x0D)
        if not (notify and notify[1][0] in voice_tasks and first_gates and later_gates
                and first_gates[0] == later_gates[0]):
            continue
        first_notify = first_gates.end()
        state_store = first_notify + 13
        state_addr = rom[state_store + 3:state_store + 5]
        if (rom[first_notify:state_store] == notify[0].replace(b'\x21\x00\x02', b'\x21\x00\x01', 1)
                and rom[state_store:state_store + 3] == b'\x3e\x01\x32'
                and rom[notify.end():notify.end() + 4] == b'\xaf\x32' + state_addr):
            yield dict(ring_on=hex(on), ring_abandon=hex(state), notify=hex(notify.start()),
                       task_signals=word_hex(m[1]), signal_routine=word_hex(notify[2]),
                       voice_task=notify[1][0],
                       ring_disable=word_hex(first_gates[1]), ui_flags=word_hex(first_gates[2]),
                       ring_task_state=word_hex(state_addr))


def data_call_candidates(rom):
    return [dict(offset=hex(m.start()), data_call_state=word_hex(m[1])) for m in DATA_TIMEOUT.finditer(rom)]


def ncc_setup_candidates(rom, data_calls, *, state_delta=0x2D):
    # This is a candidate filter, not proof of the layout or a patch gate.
    states = {int(c['data_call_state'], 16) + state_delta for c in data_calls} if state_delta is not None else None
    return [dict(offset=hex(m.start()), ncc_state=word_hex(m[1]), terminal_busy=word_hex(m[2]))
            for m in NCC_SETUP.finditer(rom) if states is None or int.from_bytes(m[1], 'little') in states]


def mtr2_input_shape(chips):
    return [len(chip) for chip in chips] in ([0x100000], [0x80000, 0x80000])


def patch_discovered(chips, *, require_mtr2=False):

    if mtr2_input_shape(chips):
        stock = b''.join(chips)
        board, layout = 'mtr2', discover_mtr2(stock)
    elif not require_mtr2 and list(map(len, chips)) == [0x40000]:
        stock = chips[0]
        board, layout = 'mtr1', discover(stock)
    else:
        raise ValueError('provide a 256 KiB MTR1 control ROM, a merged 1 MiB MTR2 image, '
                         'or both 512 KiB MTR2 control chips, flash0 first')
    image, changes = assemble(stock, layout)
    return image, dict(profile=f'{board}-discovered', input_sha256=sha256(stock).hexdigest(),
                       output_sha256=sha256(image).hexdigest(), rom_size=len(image), patches=changes,
                       layout=layout, experimental=True, physical_hardware_verified=False)


def write_patch(output_dir, name, image, manifest):
    output_dir.mkdir()  # exclusive: cannot overwrite ROM inputs or a prior take
    output = output_dir / name
    with output.open('xb') as f:
        f.write(image)
    with output.with_suffix('.patch.json').open('x', encoding='utf-8') as f:
        json.dump(manifest, f, indent=2)
        f.write('\n')
    print(f"{output}\nSHA256: {manifest['output_sha256']}")


def word(raw):
    return int.from_bytes(raw, 'little')


def le(value):
    return value.to_bytes(2, 'little')


def one(pattern, rom, label):
    hits = list(re.finditer(pattern, rom, re.S))
    if len(hits) != 1:
        raise ValueError(f'{label}: expected one match, found {len(hits)}')
    return hits[0]


def discover(rom):

    if len(rom) != 0x40000:
        raise ValueError('expected a 256 KiB MTR1 control ROM')
    ring, calls = list(ring_candidates(rom)), data_call_candidates(rom)
    setup = ncc_setup_candidates(rom, calls)
    # Some images retain a second copy of the NCC setup with the same operands.
    nccs = {(c['ncc_state'], c['terminal_busy']) for c in setup}
    if len(ring) != 1 or len(calls) != 1 or len(nccs) != 1:
        raise ValueError('ring, data-call or NCC anchors missing or ambiguous')
    ring = {k: int(v, 16) if isinstance(v, str) else v for k, v in ring[0].items()}
    data = int(calls[0]['data_call_state'], 16)
    ncc, busy = (int(x, 16) for x in next(iter(nccs)))
    init = one(rb'\x3e([\x85\x96])\xed\x39\x3a\x3e(.)\xed\x39\x38\x11(..)', rom, 'MMU setup')
    ba, ca = (init[1][0] & 15) << 12, (init[1][0] >> 4) << 12
    if ca + (init[2][0] << 12) != 0x40000:
        raise ValueError('unexpected MTR1 common RAM mapping')

    # The modem-seize body and release guard both have common-ROM veneers.
    seize = one(rb'\xcd..\x3a(..)\xf6\x07\x32\1\x6f\x26\0\xe5\x21\x60\0\xe5\xcd..\xe1\xe1\xcd..\xc9', rom, 'seize')
    guard = one(rb'\x21\xfe\xff\xcd..\xdd\x7e\x04\xe6\x80\xb7\x28\x06\xcd(..)\x22(..)', rom, 'release guard')
    guards = []
    for m in re.finditer(rb'\x21\x40\x00\xe5\xcd(..)\xe1\xb7', rom, re.S):
        addr = word(m[1]); stub = rom[addr:addr + 6]
        if addr < ba and stub[0] == 0xCD and word(stub[3:5]) + (stub[5] << 12) == guard.start():
            guards.append(addr)
    if len(set(guards)) != 1:
        raise ValueError('release guard bank stub missing or ambiguous')
    guard_addr = guards[0]
    stub = rom[guard_addr:guard_addr + 6]
    bank_call = word(stub[1:3])
    if bank_call >= ba:
        raise ValueError('bank-call runtime is not in common ROM')
    prefix = b'\xcd' + le(bank_call)
    veneers = {}
    for m in re.finditer(rb'(?=' + re.escape(prefix) + rb'(..)([\x00-\x3f]))', rom[:ba], re.S):
        veneers.setdefault(word(m[1]) + (m[2][0] << 12), set()).add(m.start())

    def veneer(physical, label):
        choices = veneers.get(physical, set())
        if len(choices) != 1:
            raise ValueError(f'{label}: common-ROM veneer missing or ambiguous')
        return next(iter(choices))

    dr = one(rb'\x3a(..)\x32(..)\xdd\x7e\x04\x6f\x26\0\x11..\x19\x3a(..)\x6e\xb5\x32\3\x3e\x01\x32..\xdd\xe1\xc9', rom, 'DR scan')
    scan_phys, disable_phys = dr.start() - 0xD5, dr.end()
    if (rom[scan_phys:scan_phys + 11] != bytes.fromhex('dde5dd210000dd39dd7e08')
            or rom[disable_phys:disable_phys + 13] != bytes.fromhex('dde5dd210000dd39dd7e04feff')):
        raise ValueError('DR scan prologues do not match')
    ring_disable = ring['ring_on'] - 0x24D
    if rom[ring_disable:ring_disable + 8] != bytes.fromhex('dde5dd210000dd39'):
        raise ValueError('ring disable prologue does not match')
    mode = one(rb'\x3e\x01\xdd\x77\xff\x18\x06\x3a(..)\xdd\x77\xff\xdd\x7e\xff',
               rom[ring_disable:ring['ring_on']], 'ring configuration')
    timer = one(rb'\xdd\xe5\xdd\x21\0\0\xdd\x39\xdd\x5e\x06\xdd\x56\x07\xdd\x4e\x08\xdd\x46\x09\xdd\xe1\xdd\xe5\xcd', rom[:ba], 'timer setup')
    clock = word(guard[1])
    elapsed = rb'\x2a(..)\xc9\xeb\x2a\1\xaf\xed\x52'
    if not re.match(elapsed, rom[clock:clock + 12], re.S):
        raise ValueError('clock routine does not match')
    start_time = one(rb'\x2a(..)\xe5\xcd' + re.escape(le(clock + 4)) + rb'\xd1\x11\xf4\x01',
                     rom[int(calls[0]['offset'], 16):][:0x40], 'call timestamp')

    cr = list(re.finditer(rb'\x1e([\x19\x1b])\x2e\0\xcd(..)\xc9', rom, re.S))
    tx, rx = [m for m in cr if m[1] == b'\x1b'], [m for m in cr if m[1] == b'\x19']
    if len(tx) != 3 or len(rx) != 1 or len({m[2] for m in cr}) != 1:
        raise ValueError('modem CR0 helpers missing or ambiguous')
    write = word(tx[0][2])
    writers = [p for p in range(write, len(rom), 0x1000)
               if re.match(bytes.fromhex('cb25cb25cb25cb25') + rb'\xcd..\x3a', rom[p:p+12], re.S)]
    if len(writers) != 1:
        raise ValueError('modem writer missing or ambiguous')
    delta = writers[0] - write
    if not ba <= write < ca or delta < 0 or delta % 0x1000:
        raise ValueError('modem writer bank mapping does not match')
    if not all(ba <= m.start() - delta < ca for m in cr):
        raise ValueError('modem CR0 helpers are not in the writer bank')

    # Use padding at the end of common ROM, not interior runs (which can be tables).
    end_padding = ba - len(rom[:ba].rstrip(b'\0'))
    if end_padding >= 336:
        origin = (ba - end_padding + 15) & ~15
    else:
        # CNB-family common ROM has a documented free window here, also
        # used by the earlier modem shims. Do not pick arbitrary interior zeros.
        if not (ring['ring_on'] == 0x2624D and bank_call == 0x43FB):
            raise ValueError('no sufficiently large common-ROM tail padding')
        origin = 0x1360
        if any(rom[origin:origin + 322]):
            raise ValueError('CNB common-ROM window occupied')
    if ba - origin < 322:
        raise ValueError('insufficient aligned common-ROM padding')
    # Experimental only: absence of literals does not rule out indirect RAM use.
    scratch = next((a for a in range(ca + 0x300, ca + 0x320, 2)
                    if le(a) not in rom and le(a + 1) not in rom), None)
    if scratch is None:
        raise ValueError('no scratch pair without direct ROM references')
    if word(dr[1]) != ring['task_signals'] + 2:
        raise ValueError('kernel task globals do not match')
    if not re.search(rb'\x3e\x01\x32' + re.escape(le(busy + 1)), rom):
        raise ValueError('native line-seized store not found')
    if b'\x2a' + le(ncc - 5) + b'\x7d\xe6\x20' not in rom:
        raise ValueError('native CALL_IN pending dialog not found')
    installed = {word(m[1]) for m in re.finditer(rb'\x2a(..)\x11\x2e\x1f\xb7\xed\x52', rom, re.S)}
    stabilization = rb'\x3e\x0b\x32' + re.escape(le(data)) + (
        rb'\x2a(..)\xe5\x21\x01\0\xe5\xcd..\xe1\xe1\x21\x02\0\xe5\x21\x07\0\xe5\xcd..\xe1\xe1')
    delays = {word(m[1]) for m in re.finditer(stabilization, rom, re.S)}
    scan_pro = re.match(rb'\xdd\xe5\xdd\x21\0\0\xdd\x39\xdd\x7e\x08\x6f\x26\0\x11\x03\0\xcd..\x11(..)\x19',
                        rom[scan_phys:scan_phys+24], re.S)
    return dict(board='mtr1', origin=origin, mode=word(mode[1]), signals=ring['task_signals'],
                ring_state=ring['ring_task_state'], ui=ring['ui_flags'], data=data, ncc=ncc,
                pending=ncc - 5, busy=busy, seized=busy + 1, offhook=busy + 2,
                notify=ring['signal_routine'], clock=clock, timer=timer.start(),
                write=write, writer_bank=delta >> 12, bank_call=bank_call, ring_count=scratch,
                answer_flag=scratch + 1, guard=guard_addr, seize=veneer(seize.start(), 'seize'),
                ring_disable=veneer(ring_disable, 'ring disable'),
                scan=veneer(scan_phys, 'DR enable'), scan_disable=veneer(disable_phys, 'DR disable'),
                dr_notify=word(dr[2]), start_time=word(start_time[1]), first=ring['ring_on'],
                later=ring['ring_abandon'], cr0=tuple(m.start() + 4 for m in tx), tx_off=rx[0].start() + 4,
                ring_enabled=ring['ring_task_state'] + 2, data_error=ncc - 8,
                ring_block=ring['ring_disable'], clock_word=word(rom[clock+1:clock+3]), guard_timestamp=word(guard[2]),
                installed_word=next(iter(installed)) if len(installed) == 1 else None,
                carrier_delay=next(iter(delays)) if len(delays) == 1 else None,
                dr_config=word(scan_pro[1]) if scan_pro else None)


def literal(data):
    return re.escape(data)


def discover_mtr2(rom):

    if len(rom) != 0x100000:
        raise ValueError('expected both MTR2 control chips (512 KiB each)')
    if not rom[0xc0000:0xc0008] == b'\xf3\x0e\x01\xc3\x12\x01\xff\xff':
        raise ValueError('MTR2 flash1 reset vector not found (check chip order and dumps)')
    mmu = one(rb'\x3e\x85\xed\x39\x3a\x3e\xb8\xed\x39\x38\x11..',
              rom[:0x5000], 'MTR2 reset MMU setup (check flash0 comes first)')
    ba, ca = 0x5000, 0x8000
    rings = list(ring_candidates(rom[:0xc0000], voice_tasks=range(1, 64)))
    if len(rings) != 1:
        raise ValueError('MTR2 ring task missing or ambiguous')
    ring = {k: int(v, 16) if isinstance(v, str) else v for k, v in rings[0].items()}
    first = ring['ring_on']
    common = rom[:ba]
    control = rom[:0xc0000]
    pro = rb'\xdd\xe5\xdd\x21\0\0\xdd\x39'
    rd = one(pro + rb'\xcd(..)\x3a(..)\xe6\xef\x32\2\x6f\x26\0\xe5\x21\x40\0\xe5\xcd..\xe1\xe1\xcd(..)'
             + literal(b'\x3a' + le(ring['ring_disable'])) + rb'\xdd\x6e\x04\xb5\x32'
             + literal(le(ring['ring_disable'])) + rb'\xe6\x03\xb7\x28\x04\xaf\x32(..)'
             rb'\x21(.\x00)\xe5\xcd..\xe1\x21\5\xe5\xcd..\xe1\xdd\xe1\xc9',
             rom[first-0x400:first], 'MTR2 ring disable')
    rd_phys = first - 0x400 + rd.start()
    mode = one(rb'\x3e\x01\xdd\x77\xff\x18\x06\x3a(..)\xdd\x77\xff\xdd\x7e\xff',
               rom[rd_phys:first], 'MTR2 ring config')

    guard = one(rb'\x21\xfe\xff\xcd..\xdd\x7e\x04\xe6\x80\xb7\x28\x06\xcd(..)\x22(..)',
                control, 'MTR2 release guard')
    clock = word(guard[1])
    if not re.match(rb'\x2a(..)\xc9\xeb\x2a\1\xaf\xed\x52', common[clock:clock+12], re.S):
        raise ValueError('MTR2 clock/elapsed routines do not match')
    init_timer = one(pro + rb'\xdd\x5e\x06\xdd\x56\x07\xdd\x4e\x08\xdd\x46\x09\xdd\xe1\xdd\xe5\xcd',
                     common, 'MTR2 timer')
    seize_calls = []
    for m in re.finditer(rb'\x21\x40\0\xe5\xcd(..)\xe1\xb7\xca..\xcd(..)\x3e\x01\x32(..)', control, re.S):
        addr = word(m[1]); stub = rom[addr:addr+6]
        if (addr + 6 <= ba and stub[0] == 0xcd and ba <= word(stub[3:5]) < ca
                and word(stub[3:5]) + stub[5] * 0x1000 == guard.start()):
            seize_calls.append(m)
    if len({m.groups() for m in seize_calls}) != 1:
        raise ValueError('MTR2 release guard/seize caller missing or ambiguous')
    guard_addr, seize, seized = map(word, seize_calls[0].groups())
    bank_call = word(rom[guard_addr+1:guard_addr+3])
    if not 0 < bank_call < ba:
        raise ValueError('MTR2 bank-call routine outside common ROM')
    prefix = b'\xcd' + le(bank_call)

    def target(addr):
        stub = common[addr:addr+6]
        if len(stub) != 6 or not stub.startswith(prefix) or not ba <= word(stub[3:5]) < ca:
            raise ValueError(f'not an MTR2 bank veneer at {addr:#x}')
        return word(stub[3:5]) + stub[5] * 0x1000

    def veneer(physical, label):
        matches = {m.start() for m in re.finditer(rb'(?=' + literal(prefix) + rb'...)', common, re.S)
                   if ba <= word(rom[m.start()+3:m.start()+5]) < ca and target(m.start()) == physical}
        if len(matches) != 1:
            raise ValueError(f'MTR2 {label}: veneer missing or ambiguous')
        return next(iter(matches))

    s = target(seize)
    one(literal(b'\xcd' + rd[1]) + rb'(?:\xcd..|\x3a..\x6f\x26\0\xe5\xcd..\xe1)'
        + literal(b'\x3a' + rd[2] + b'\xf6\x07\x32' + rd[2] + b'\x21\x40\0\x4d\x44\xed\x79\xcd' + rd[3] + b'\xc9'),
        rom[s:s+33], 'MTR2 seize body')

    # The secondary data task can share timeout code. Require the primary
    # timeout to lead into the native guard + seize sequence.
    data_hits = [(m, x) for m in DATA_TIMEOUT.finditer(control) for x in seize_calls
                 if m.end() < x.start() < m.end()+0x110]
    if len(data_hits) != 1:
        raise ValueError('MTR2 primary data task missing or ambiguous')
    timeout, caller = data_hits[0]
    seized_check = one(literal(b'\x3a' + le(seized)) + rb'\xb7\x28\x10\x21\x02\0\xe5\x21(.\x00)\xe5\xcd..\xe1\xe1\xc3..',
                       rom[timeout.end():caller.start()], 'MTR2 data task number')
    time = one(rb'\x2a(..)\xe5\xcd' + literal(le(clock+4)) + rb'\xd1\x11\xf4\x01\xb7\xed\x52\x38\x09\x28\x07'
               rb'\x3e\x06\x32(..)\x18\x05\x3e\x05\x32\2',
               rom[timeout.end():caller.start()], 'MTR2 data timestamp/error')
    data_task = word(seized_check[1])
    scan_call = one(rb'\x21\xff\0\xe5\xcd(..)\xe1\x21\x03\0\xe5\x21\x28\0\xe5\x21\x02\0\xe5\xcd(..)\xe1\xe1\xe1\x3e\x0a\x32'
                    + literal(timeout[1]), rom[caller.end():caller.end()+0x500], 'MTR2 data DR calls')
    scan_disable, scan = map(word, scan_call.groups())
    carrier_delay = one(rb'\x3e\x0b\x32'+literal(timeout[1])+rb'\x2a(..)\xe5\x21\x01\0\xe5\xcd..\xe1\xe1\x21\x02\0\xe5\x21'
                        +literal(le(data_task))+rb'\xe5\xcd..\xe1\xe1',
                        rom[max(0, timeout.start()-0x180):caller.end()+0x600], 'MTR2 carrier stabilization delay')
    sp, sd = target(scan), target(scan_disable)
    scan_pro = re.match(pro + rb'\xdd\x7e\x08\x6f\x26\0\x11\x03\0\xcd..\x11(..)\x19', rom[sp:sp+24], re.S)
    if not (0 < sd - sp < 0x140 and scan_pro and re.match(pro + rb'\xdd\x7e\x04\xfe\xff', rom[sd:sd+13])):
        raise ValueError('MTR2 DR scan prologues do not match')
    dr = one(literal(b'\x3a' + le(ring['task_signals']+2)) + rb'\x32(..)\xdd\x7e\x04\x6f\x26\0\x11..\x19\x3a(..)\x6e\xb5\x32\2\x3e\x01\x32..\xdd\xe1\xc9',
             rom[sp:sd], 'MTR2 DR notification')

    # The pending word is used by native CALL_IN scheduling in the primary
    # data task; it need not have a fixed displacement from either state.
    pending = one(rb'\x2a(..)\x7d\xe6\x20\x6f\x26\0\x7d\xb4\x28\x13\x2a\1\x2e\0\x7c\xe6\x07\x67\x7d\xb4\x20\x06\xaf\x32(..)\x18\x05\x3e\x01\x32\2\xc9',
                  rom[timeout.end():timeout.end()+0x900], 'MTR2 CALL_IN pending word')
    nccs = {(m[1], m[2]) for m in NCC_SETUP.finditer(control)
            if (b'\x3a' + m[1] + b'\xb7' in control and
                re.search(literal(b'\x3a' + m[2]) + rb'\xe6[\x02\x07]\xb7', control))}
    if len(nccs) != 1:
        raise ValueError('MTR2 NCC setup missing or ambiguous')
    ncc, busy = map(word, next(iter(nccs)))
    # Export the installed-state word for the emulator fixture. This is
    # metadata only; the patch does not change provisioning state.
    installed = {word(m[1]) for m in re.finditer(rb'\x2a(..)\x11\x2e\x1f\xb7\xed\x52', control, re.S)}
    # Both native hook transitions assign this byte. Do not use the
    # adjacent terminal display/call state as a proxy for handset state.
    offhooks = {word(m[1]) for m in re.finditer(
        rb'\xdd\x7e\xff\xfe\x60\x28\x07\xdd\x7e\xff\xfe\x6c\x20.\xaf\x32(..)'
        rb'.{0,100}?\xdd\x7e\xff\xfe\x62\x28\x07\xdd\x7e\xff\xfe\x6e\x20.\x3e\x01\x32\1',
        control, re.S)}
    if len(offhooks) != 1:
        raise ValueError('MTR2 native hook-switch state missing or ambiguous')

    # Find the control firmware's SSI writer and only the immediate CR0
    # writes in its own bank. Embedded maintenance/voice images have
    # lookalike helpers but are a different execution context.
    cr = rb'\x1e([\x19\x1b])\x2e\0\xcd(..)'
    writer_sig = rb'(?:\xcb\x25){4}\xcd' + literal(rd[1]) + rb'\x3a..\xcb\xd7\xe6\xef\xe6\xdf\xe6\xbf\xb5\x06\x08'
    writers = set()
    for m in re.finditer(cr + rb'\xc9', control, re.S):
        write = word(m[2])
        for phys in range(write, len(control), 0x1000):
            delta = phys - write
            if ba <= write < ca and delta + ba <= m.start() < delta + ca and re.match(writer_sig, rom[phys:phys+28], re.S):
                writers.add((write, delta))
    if len(writers) != 1:
        raise ValueError('MTR2 SSI writer missing or ambiguous')
    write, delta = next(iter(writers))
    sites = list(re.finditer(cr, rom, re.S))
    sites = [m for m in sites if delta + ba <= m.start() and m.end() <= delta + ca and word(m[2]) == write]
    tx = tuple(m.start()+4 for m in sites if m[1] == b'\x1b')
    # NSA's selectable modem mode has a second CR0 value in the alternate
    # branch of TX mark/data-on. Confirm it against the paired normal branch.
    call_write = literal(b'\xcd' + le(write))
    alt = (rb'\x7d\xfe\0(?:\x28\x08|\x28\x0f\x1e.\x2e\x01' + call_write + rb')'
           rb'\x1e\x1b\x2e\0' + call_write + rb'\xc9\x1e.\x2e\x01' + call_write
           + rb'\x1e\xa3\x2e\0(' + call_write + rb')\xc9')
    tx = tuple(sorted((*tx, *(delta + ba + m.start(1) for m in re.finditer(alt, rom[delta+ba:delta+ca], re.S)))))
    rx = tuple(m.start()+4 for m in sites if m[1] == b'\x19')
    if not tx or not rx or not any(rom[at+3] == 0xc9 for at in rx):
        raise ValueError('MTR2 native CR0 transmit/receive writes not found')

    # Use the end of common ROM only. Never interpret an arbitrary zero
    # run inside the image (e.g. a provisioning table) as free space.
    fill = common[-1]
    if fill not in (0, 255):
        raise ValueError('MTR2 common ROM has no tail padding')
    padding = len(common.rstrip(bytes([fill])))
    origin = (padding+15) & ~15
    ring_disable = veneer(rd_phys, 'ring disable')
    task_delta = rom[ring_disable+5] * 0x1000
    if not ba <= first - task_delta < ca or not ba <= ring['ring_abandon'] - task_delta < ca:
        raise ValueError('MTR2 ring hooks outside the ring task bank')
    ring_delta = 0
    ring_phys = origin
    ring_fill = fill
    if ba-origin < 336:
        ring_delta = task_delta
        end = ring_delta + ca
        ring_fill = rom[end-1]
        if ring_fill not in (0, 255):
            raise ValueError('MTR2 ring bank has no tail padding')
        start = ba + ring_delta
        ring_phys = (start + len(rom[start:end].rstrip(bytes([ring_fill]))) + 15) & ~15
        if not start <= first < ring_phys or end-ring_phys < 320 or ba-origin < 32:
            raise ValueError('insufficient MTR2 common/ring-bank tail padding')
    scratch = next((a for a in range(ca+0x304, ca+0x320, 2)
                    if le(a) not in rom and le(a+1) not in rom), None)
    if scratch is None:
        raise ValueError('no MTR2 scratch pair without direct ROM references')
    return dict(board='mtr2', origin=origin, code_fill=fill,
                ring_phys=ring_phys, ring_origin=ring_phys-ring_delta, ring_fill=ring_fill,
                mode=word(mode[1]), signals=ring['task_signals'], ring_state=ring['ring_task_state'],
                ring_enabled=word(rd[4]), ui=ring['ui_flags'], data=word(timeout[1]), data_error=word(time[2]),
                ncc=ncc, pending=word(pending[1]), busy=busy, seized=seized, offhook=next(iter(offhooks)),
                notify=ring['signal_routine'], clock=clock, timer=init_timer.start(),
                clock_word=word(rom[clock+1:clock+3]), guard_timestamp=word(guard[2]),
                installed_word=next(iter(installed)) if len(installed) == 1 else None,
                data_task=data_task, ring_task=word(rd[5]), voice_task=ring['voice_task'],
                write=write, writer_bank=delta>>12, bank_call=bank_call,
                ring_count=scratch, answer_flag=scratch+1, guard=guard_addr, seize=seize,
                ring_disable=ring_disable, ring_block=ring['ring_disable'], ring_bank=task_delta>>12,
                scan=scan, scan_disable=scan_disable, dr_config=word(scan_pro[1]), carrier_delay=word(carrier_delay[1]),
                dr_notify=word(dr[1]), start_time=word(time[1]), first=first, later=ring['ring_abandon'], cr0=tx, tx_off=rx,
                mmu_setup=mmu.start())


class Assembler:
    """Small byte/label emitter; every instruction is explicit below."""
    def __init__(self, origin):
        self.origin, self.code, self.labels, self.fixups = origin, bytearray(), {}, []

    def emit(self, text):
        self.code.extend(bytes.fromhex(text))

    def label(self, name):
        assert name not in self.labels
        self.labels[name] = self.origin + len(self.code)

    def jump(self, opcode, label):
        self.emit(opcode)
        self.fixups.append((len(self.code), label))
        self.emit('00 00')

    def finish(self):
        for offset, label in self.fixups:
            self.code[offset:offset + 2] = self.labels[label].to_bytes(2, 'little')
        return bytes(self.code)


ANSWER_MARK = 0xA5


def assemble(stock, p):
    origin, ring_count, answer_flag = (p[k] for k in ('origin', 'ring_count', 'answer_flag'))
    mode, signals, ring_state = (p[k] for k in ('mode', 'signals', 'ring_state'))
    data, ncc, pending = (p[k] for k in ('data', 'ncc', 'pending'))
    busy, offhook, seized = (p[k] for k in ('busy', 'offhook', 'seized'))
    notify, clock, timer, write = (p[k] for k in ('notify', 'clock', 'timer', 'write'))
    ring_asm = a = Assembler(p.get('ring_origin', origin))
    ring_phys = p.get('ring_phys', origin)

    def op(opcode, operand):
        a.emit(f'{opcode:02x}' + operand.to_bytes(2, 'little').hex())

    def signal(task, flags):
        invoke(notify, task, flags)

    def invoke(target, *args):
        for value in reversed(args):
            op(0x21, value)
            a.emit('E5')
        op(0xCD, target)
        a.emit('E1' * len(args))

    a.label('first_ring')
    a.emit('F5 C5 D5 E5')
    op(0x3A, signals); a.emit('E6 10'); a.jump('CA', 'first_exit')
    a.emit('AF'); op(0x32, ring_count)
    a.jump('CD', 'count_ring')
    if p.get('board') == 'mtr2':
        # Reserve an eligible delayed-answer call for the modem. On NCE,
        # native first-ring notification can seize the line before ring two.
        # Set the native RINGING state ourselves, but skip the notification.
        op(0x3A, ring_count); a.emit('B7'); a.jump('CA', 'first_exit')
        a.emit('3E 01'); op(0x32, ring_state)
        a.emit('E1 D1 C1 F1'); op(0x2A, signals); a.emit('AF C9')
    a.label('first_exit')
    a.emit('E1 D1 C1 F1'); op(0x2A, signals); a.emit('7D E6 10 C9')

    a.label('later_ring')
    a.emit('F5 C5 D5 E5')
    op(0x3A, signals); a.emit('E6 40'); a.jump('C2', 'abandoned')
    op(0x3A, signals); a.emit('E6 10'); a.jump('CA', 'later_exit')
    a.jump('CD', 'count_ring'); a.jump('C3', 'later_exit')
    a.label('abandoned')
    a.emit('AF'); op(0x32, ring_count)
    a.label('later_exit')
    a.emit('E1 D1 C1 F1'); op(0x2A, signals); a.emit('7D E6 40 C9')

    a.label('count_ring')
    op(0x3A, mode); a.emit('FE 02 D8 FE 04 D0')

    def threshold():
        a.emit('FE 02'); a.jump('CA', 'answer')
        op(0x3A, ring_count); a.emit('3C'); op(0x32, ring_count); a.emit('47')
        op(0x3A, mode + 1); a.emit('B8'); a.jump('DA', 'answer'); a.emit('C0')
        a.label('answer')

    if p.get('board') != 'mtr2':
        threshold()
    idle_bytes = (offhook, data, ncc)
    if p.get('board') == 'mtr2':
        idle_bytes += (seized,)
        op(0x3A, p['ring_block']); a.emit('E6 07 C0')
    for address in idle_bytes:
        op(0x3A, address); a.emit('B7 C0')
    op(0x3A, busy); a.emit('E6 07 C0')
    op(0x3A, p['ui']); a.emit('E6 20 C8')
    if p.get('board') == 'mtr2':
        op(0x3A, mode); threshold()
    invoke(p['guard'], 0x40)  # Native release guard, QUERY.
    a.emit('B7 C8')

    a.emit('3E 01'); op(0x32, ncc); op(0x32, seized)
    op(0x3A, busy); a.emit('F6 02'); op(0x32, busy)
    op(0x2A, pending); a.emit('7D F6 20 6F'); op(0x22, pending)
    a.emit('AF'); op(0x32, ring_count)
    invoke(p['seize'])
    a.emit('2E 01 1E 08'); a.jump('CD', 'modem_write')
    a.emit('2E 00 1E 1A'); a.jump('CD', 'modem_write')
    a.emit(f'3E {ANSWER_MARK:02X}'); op(0x32, answer_flag)
    invoke(p['ring_disable'], 2)  # Disable ring detection: DATA.
    invoke(p['scan_disable'], 0xFF)
    invoke(p['scan'], 2, 0x28, 3)
    a.emit(f"3E {p.get('data_task', 7):02X}"); op(0x32, p['dr_notify'])
    invoke(clock); op(0x22, p['start_time'])
    invoke(timer, p.get('data_task', 7), 2, 3000)
    a.emit('3E 0A'); op(0x32, data)
    op(0x3A, ring_state); a.emit('FE 01'); a.jump('C2', 'reset_ring')
    signal(p.get('voice_task', 9), 0x0200)
    a.label('reset_ring')
    signal(p.get('ring_task', 0x17), 0x40)
    a.emit('C9')

    a.label('modem_write')
    op(0xCD, p['bank_call']); a.emit(write.to_bytes(2, 'little').hex() + f"{p['writer_bank']:02x}")
    if ring_phys != origin:
        a = Assembler(origin)
    a.label('cr0')
    a.emit('F5'); op(0x3A, answer_flag); a.emit(f'FE {ANSWER_MARK:02X} 20 02 1E 1A F1'); op(0xC3, write)
    a.label('tx_off')
    a.emit('F5 AF'); op(0x32, answer_flag); a.emit('F1'); op(0xC3, write)

    code = a.finish()
    image = bytearray(stock)
    changes = []

    def patch(at, before, after, label):
        end = at + len(before)
        if not 0 <= at < end <= len(stock) or stock[at:end] != before or len(before) != len(after):
            raise ValueError(f'anchor mismatch: {label} at {at:#x}')
        if any(at < p['offset'] + len(p['expected']) // 2 and p['offset'] < end for p in changes):
            raise ValueError(f'overlapping patch: {label} at {at:#x}')
        image[at:end] = after
        changes.append(dict(offset=at, label=label, expected=before.hex(), replacement=after.hex()))

    def call(assembler, label):
        return b'\xcd' + assembler.labels[label].to_bytes(2, 'little')

    patch(origin, bytes([p.get('code_fill', 0)]) * len(code), code, 'fixed_callin_module')
    if ring_phys != origin:
        banked = ring_asm.finish()
        patch(ring_phys, bytes([p['ring_fill']]) * len(banked), banked, 'banked_ring_module')
    first, later = p['first'], p['later']
    for at, mask, label in ((first, 0x10, 'first_ring'), (later, 0x40, 'later_ring')):
        patch(at, b'\x2a' + signals.to_bytes(2, 'little') + b'\x7d\xe6' + bytes([mask]),
              call(ring_asm, label) + bytes(3), label)
    native_write = b'\xcd' + write.to_bytes(2, 'little')
    for at in p['cr0']:
        patch(at, native_write, call(a, 'cr0'), 'preserve_answer_modem_mode')
    rx = p['tx_off']
    for at in (rx,) if isinstance(rx, int) else rx:
        patch(at, native_write, call(a, 'tx_off'), 'clear_answer_mode')
    return bytes(image), changes


SELF_TEST_JS = "// Fixtures supply missing provisioning RAM, not modem or task outcomes.\n// node test_mtr2_callin.mjs [--rings N] <emulator dir> <patched.bin> <manifest.json> [...]\nimport assert from 'node:assert/strict';\nimport {createHash} from 'node:crypto';\nimport {readFileSync} from 'node:fs';\nimport {resolve} from 'node:path';\nimport {pathToFileURL} from 'node:url';\n\nconst args = process.argv.slice(2);\nconst rings = args[0] === '--rings' ? Number(args.splice(0, 2)[1]) : 2;\nassert.ok(Number.isInteger(rings) && rings >= 2 && rings <= 255, 'rings must be 2..255');\nconst [emulator, ...files] = args;\nassert.ok(emulator && files.length && files.length % 2 === 0, 'provide ROM/manifest pair(s)');\nconst {Machine} = await import(pathToFileURL(resolve(emulator, 'machine.js')));\n\nfor (let i = 0; i < files.length; i += 2) {\n  const [filename, json] = files.slice(i, i + 2);\n  const rom = readFileSync(filename);\n  const manifest = JSON.parse(readFileSync(json, 'utf8'));\n  const p = manifest.layout;\n  assert.equal(createHash('sha256').update(rom).digest('hex'), manifest.output_sha256);\n  const board = p.board ?? (rom.length === 0x40000 ? 'mtr1' : 'mtr2');\n  assert.ok(['mtr1', 'mtr2', 'mtr1-coin-basic'].includes(board));\n  const mtr2 = board === 'mtr2';\n  for (const field of ['installed_word', 'carrier_delay', 'dr_config', 'guard_timestamp', 'clock_word', 'ring_block']) {\n    const address = p[field];\n    assert.ok(Number.isInteger(address) && address >= 0x8000 && address < 0xffff,\n      `no unambiguous RAM fixture address for ${field}`);\n  }\n  const boot = new Machine();\n  boot.load(rom, filename, [], {board});\n  const cycles = boot.msCycles(8000);\n  assert.equal(boot.run({cycles, instructions: cycles}).fault, null, filename);\n  assert.ok(boot.state().display.some(row => row.trim()), 'boot display');\n  const coldBoot = boot.snapshot();\n\n  function fixture(mode, {blocked = false, offhook = false} = {}) {\n    const m = new Machine();\n    m.load(rom, filename, [], {board});\n    m.restore(coldBoot);\n    const read = k => m.read(p[k]);\n    const writeRam = (a, v) => {\n      assert.ok(Number.isInteger(a) && a >= 0x8000 && a <= 0xffff && m.physical(a) >= m.board.ramStart,\n        `fixture address is not mapped to RAM: ${a}`);\n      m.write(a, v);\n    };\n    const put = (k, v) => writeRam(p[k], v);\n    const word = k => read(k) | m.read(p[k]+1) << 8;\n    const putWord = (k, v) => { put(k, v & 255); writeRam(p[k]+1, (v >> 8) & 255); };\n    const run = ms => {\n      const cycles = m.msCycles(ms);\n      const result = m.run({cycles, instructions: cycles});\n      assert.equal(result.fault, null, filename);\n    };\n    const line = data => m.deviceEvent('line', data);\n    assert.equal(read('answer_flag'), 0, 'scratch must be clear after boot');\n    for (const k of ['offhook', 'ncc', 'data', 'busy', 'seized', 'ring_state', 'answer_flag', 'ring_count', 'ring_block']) put(k, 0);\n    put('offhook', +offhook);\n    put('ring_block', +blocked);\n    putWord('pending', 0);\n    putWord('carrier_delay', 10);\n    // Provisioned modem debounce parameters. The demo boots with the\n    // relevant records all zero; copy the observed retail defaults there.\n    for (const [index, record] of [[3, [1, 10, 10]], [4, [1, 3, 20]]]) {\n      const a = p.dr_config + 3*index;\n      if (![0, 1, 2].some(i => m.read(a+i))) record.forEach((v, i) => writeRam(a+i, v));\n    }\n    putWord('guard_timestamp', word('clock_word') - 300);\n    putWord('mode', mode | (rings << 8));\n    put('ui', read('ui') | 0x20);\n    putWord('installed_word', 0x1f2e);\n    put('ring_enabled', 1);\n    if (mtr2) m.output(m.board.control, m.ports[m.board.control] | 0x10);\n    return {m, run, line, read, word};\n  }\n\n  function answered({m, read, word}) {\n    assert.equal(read('data'), 10, 'native waiting-for-carrier state');\n    assert.equal(read('ncc'), 1, 'native NCC setup state');\n    assert.equal(read('busy') & 2, 2);\n    assert.equal(word('pending') & 0x20, 0x20, 'CALL_IN dialog queued');\n    assert.equal(read('ring_enabled'), 0);\n    assert.equal(read('answer_flag'), 0xa5);\n    assert.equal(m.relayState & 3, 3);\n    assert.equal(m.devices.modem.controls[0], 0x1a);\n    assert.equal(m.devices.dialed, '');\n  }\n\n  function carrier(incoming) {\n    incoming.line({ring: false, carrier: true, dialTone: false});\n    let established = false;\n    for (let n = 0; n < 250 && !established; n++) {\n      incoming.run(4);\n      established = incoming.read('data') === 12;\n    }\n    assert.ok(established, `${filename}: native data task must accept simulated carrier`);\n    assert.equal(incoming.m.devices.modem.controls[0], 0x1a, 'TX data-on must preserve answer mode');\n  }\n\n  const incoming = fixture(2);\n  incoming.line({ring: true}); incoming.run(400);\n  answered(incoming);\n  carrier(incoming);\n\n  const delayed = fixture(3);\n  for (let i = 1; i <= rings; i++) {\n    delayed.line({ring: true}); delayed.run(400);\n    if (i === rings) break;\n    assert.equal(delayed.read('ring_count'), i, `ring ${i}/${rings} was not counted`);\n    assert.equal(delayed.read('answer_flag'), 0, `answered early on ring ${i}`);\n    assert.equal(delayed.read('data'), 0, `data call started early on ring ${i}`);\n    delayed.line({ring: false}); delayed.run(900);\n  }\n  answered(delayed);\n  carrier(delayed);\n\n  const deniedCases = [[0, {}], [1, {}], [2, {offhook: true}]];\n  if (mtr2) deniedCases.push([2, {blocked: true}]);\n  const relayFailures = [];\n  for (const [mode, opts] of deniedCases) {\n    const denied = fixture(mode, opts);\n    let answerModeSeen = false;\n    let relaySeized = Boolean(denied.m.relayState & 1);\n    const output = denied.m.output.bind(denied.m);\n    denied.m.output = (...args) => {\n      output(...args);\n      if (denied.m.devices.modem.controls[0] === 0x1a) answerModeSeen = true;\n      if (denied.m.relayState & 1) relaySeized = true;\n    };\n    const assertNoPickup = () => {\n      assert.equal(denied.read('data'), 0, `mode ${mode} started a data call`);\n      assert.equal(denied.read('answer_flag'), 0, `mode ${mode} ran the answer hook`);\n      assert.equal(answerModeSeen, false, `mode ${mode} programmed answer mode`);\n    };\n    for (let i = 0; i < rings; i++) {\n      denied.line({ring: true}); denied.run(400);\n      assertNoPickup();\n      denied.line({ring: false}); denied.run(900);\n      assertNoPickup();\n    }\n    if (mode <= 1 && relaySeized) relayFailures.push(mode);\n  }\n  assert.deepEqual(relayFailures, [], `modem relay seized in mode(s) ${relayFailures.join(', ')} without entering answer mode`);\n  console.log(`${board}: answered on rings 1 and ${rings}, accepted carrier in both; no modem pickup in modes 0 and 1`);\n}\n"


def run_self_test(emulator, rings, image, manifest):
    if not (emulator / 'machine.js').is_file():
        raise ValueError('--self-test must point to the emulator directory containing machine.js')
    with TemporaryDirectory(prefix='millennium-callin-') as tmp:
        root = Path(tmp)
        harness, rom, layout = (root / n for n in ('self-test.mjs', 'candidate.bin', 'candidate.json'))
        harness.write_text(SELF_TEST_JS, encoding='utf-8')
        rom.write_bytes(image)
        layout.write_text(json.dumps(manifest), encoding='utf-8')
        try:
            result = subprocess.run(['node', str(harness), '--rings', str(rings), str(emulator.resolve()),
                                     str(rom), str(layout)], capture_output=True, text=True, encoding='utf-8')
        except FileNotFoundError as error:
            raise ValueError('emulator self-test requires Node.js on PATH') from error
        if result.returncode:
            raise ValueError(f'emulator self-test failed (no ROM written):\n{result.stderr.strip() or result.stdout.strip()}')
        return dict(result='passed', immediate_rings=1, delayed_rings=rings, no_pickup_modes=[0, 1],
                    provisioning='emulator_ram_only',
                    stdout=result.stdout.strip())


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='action', required=True)
    patch = commands.add_parser('patch', help='write an experimental ROM and patch manifest')
    patch.add_argument('roms', nargs='+', type=Path, help='merged ROM, or MTR2 flash0 followed by flash1')
    patch.add_argument('--output-dir', type=Path, required=True, help='must not already exist')
    patch.add_argument('--mtr2', action='store_true', help='require MTR2 rather than auto-detect')
    patch.add_argument('--self-test', type=Path, metavar='EMULATOR_DIR', help='test inbound calls in an isolated emulator')
    patch.add_argument('--rings', type=int, metavar='N', help='delayed-answer test threshold (2..255, default 2)')
    args = parser.parse_args()
    if args.rings is not None and (args.self_test is None or not 2 <= args.rings <= 255):
        parser.error('--rings requires --self-test and a value from 2 to 255')
    try:
        if args.output_dir.exists():
            raise ValueError('output directory must not already exist')
        if len(set(p.resolve() for p in args.roms)) != len(args.roms):
            raise ValueError('provide each input file only once')
        image, manifest = patch_discovered([load_rom(p) for p in args.roms], require_mtr2=args.mtr2)
        name = f'{args.roms[0].stem}_callin_experimental.bin'
        if args.self_test is not None:
            manifest['self_test'] = run_self_test(args.self_test, args.rings or 2, image, manifest)
            print(manifest['self_test']['stdout'])
        write_patch(args.output_dir, name, image, manifest)
    except (ValueError, OSError, AssertionError) as error:
        parser.exit(1, f'{parser.prog}: {error}\n')


if __name__ == '__main__':
    main()
